'use strict';

const path = require('path');
const fs = require('fs');

// Load the native addon from build/Release/ (sharp/drivelist pattern)
const binding = require('../build/Release/binding.node');

// Read a sibling vendor config file (sharp vendor/ pattern)
// This tests that the prelude's dlopen extraction copies the ENTIRE
// package directory, not just the .node file
const vendorConfigPath = path.join(__dirname, '..', 'vendor', 'config.json');
let vendorConfig = null;
try {
  vendorConfig = JSON.parse(fs.readFileSync(vendorConfigPath, 'utf8'));
} catch {}

module.exports = {
  // Native addon functions
  add: binding.add,
  multiply: binding.multiply,
  version: binding.version,

  // Vendor config (proves sibling files are accessible)
  vendorConfig,

  // Package metadata
  packageName: 'native-pkg',
};
